package com.termux.app.workspace;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspaceActivityRouteTest {
 @Test public void disabledStopCannotInterruptAndDoesNotChangeItsDimensions(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentStopButton b=new AgentStopButton(a);final int[] calls={0};b.setOnClickListener(v->{if(b.isEnabled())calls[0]++;});b.layout(0,0,44,44);b.performClick();assertEquals(0,calls[0]);b.setEnabled(true);b.performClick();assertEquals(1,calls[0]);assertEquals(44,b.getWidth());assertEquals(Button.class.getName(),b.getAccessibilityClassName());}
 @Test public void fourGlyphsAndEveryStateUseSameHitArea(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentStopButton b=new AgentStopButton(a);b.layout(0,0,44,44);Canvas c=new Canvas(Bitmap.createBitmap(44,44,Bitmap.Config.ARGB_8888));for(String agent:new String[]{"Codex","Claude","Gemini","OpenCode"})for(AgentIndicatorState.State state:AgentIndicatorState.State.values()){b.indicator(agent,state);b.frame(3150000000L,0);b.onDraw(c);assertEquals(state,b.state());assertEquals(44,b.getWidth());assertEquals(44,b.getHeight());assertEquals(state!=AgentIndicatorState.State.IDLE&&state!=AgentIndicatorState.State.ERROR,b.animated());}}
 @Test public void frameCadenceTargets60AcrossDifferentDisplayRefreshRates(){for(int hz:new int[]{60,90,120,144}){WorkspaceActivityLine.FrameCadence clock=new WorkspaceActivityLine.FrameCadence();int redraws=0;for(int frame=0;frame<hz*10;frame++)if(clock.due(1000000000L+Math.round(frame*1000000000d/hz)))redraws++;assertTrue(Math.abs(redraws-600)<=1);}}
 @Test public void missedFramesResumeWithoutBurstAndResetStartsImmediately(){WorkspaceActivityLine.FrameCadence clock=new WorkspaceActivityLine.FrameCadence();assertTrue(clock.due(1000000000L));assertFalse(clock.due(1000000000L));assertTrue(clock.due(5000000000L));assertFalse(clock.due(5000000000L));clock.reset();assertTrue(clock.due(5000000000L));}
 @Test public void individualMotionIsBoundedContinuousAndStaticWithoutFrames(){
  Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentStopButton b=new AgentStopButton(a);
  for(String agent:new String[]{"Codex","Claude","Gemini","OpenCode"}){
   b.indicator(agent,AgentIndicatorState.State.WORKING);b.frame(0,0);assertEquals(1,b.glyphScale(),0);assertEquals(1,b.elementBrightness(0,12),0);assertEquals(0,b.arcAngle(),0);
   float min=1,max=0;for(long time=1000000;time<9000000000L;time+=17000000L){b.frame(time,0);float brightness=b.elementBrightness(0,12);assertTrue(brightness>=.359f&&brightness<=1.001f);assertTrue(b.glyphScale()>=1&&b.glyphScale()<=1.056f);min=Math.min(min,brightness);max=Math.max(max,brightness);b.frame(time+1000000,0);assertTrue(Math.abs(b.elementBrightness(0,12)-brightness)<.005f);}assertTrue(max-min>.63f);
   for(AgentIndicatorState.State state:new AgentIndicatorState.State[]{AgentIndicatorState.State.IDLE,AgentIndicatorState.State.ERROR}){b.indicator(agent,state);b.frame(1234000000L,0);assertEquals(1,b.glyphScale(),0);assertEquals(1,b.elementBrightness(0,12),0);assertFalse(b.animated());}
   b.indicator(agent,AgentIndicatorState.State.WAITING);b.frame(1500000000L,0);assertTrue(b.glyphScale()>1);assertEquals(1,b.elementBrightness(0,12),0);
  }
 }
 @Test public void glyphsFitSmallAndLargeButtonsWithoutChangingHitArea(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentStopButton b=new AgentStopButton(a);for(int size:new int[]{20,44,96}){b.layout(0,0,size,size);for(String agent:new String[]{"Codex","Claude","Gemini","OpenCode"}){b.indicator(agent,AgentIndicatorState.State.WORKING);b.frame(1500000000L,0);b.onDraw(new Canvas(Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888)));assertTrue(b.circleRadius()<size/2f);assertEquals(size,b.getWidth());assertEquals(size,b.getHeight());}}}
 @Test public void hidingCancelsFramesAndReturningKeepsCurrentAgentState()throws Exception{
  Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a);WorkspaceActivityLine line=new WorkspaceActivityLine(a,null);AgentStopButton b=new AgentStopButton(a);
  host.addView(line,new FrameLayout.LayoutParams(300,2));host.addView(b,new FrameLayout.LayoutParams(44,44));a.setContentView(host);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();line.layout(0,0,300,2);b.layout(0,0,44,44);Object attach=org.robolectric.util.ReflectionHelpers.getField(line,"mAttachInfo");org.robolectric.util.ReflectionHelpers.setField(attach,"mWindowVisibility",View.VISIBLE);line.onWindowVisibilityChanged(View.VISIBLE);line.stopTarget(b);b.indicator("Claude",AgentIndicatorState.State.WAITING);line.working(true);
  Canvas c=new Canvas(Bitmap.createBitmap(300,2,Bitmap.Config.ARGB_8888));java.lang.reflect.Field pending=WorkspaceActivityLine.class.getDeclaredField("framePending");pending.setAccessible(true);
  try{line.onDraw(c);assertTrue("initial frame: attached="+line.isAttachedToWindow()+", shown="+line.isShown()+", window="+line.getWindowVisibility(),pending.getBoolean(line));host.setVisibility(View.GONE);assertFalse(pending.getBoolean(line));b.indicator("Gemini",AgentIndicatorState.State.RECONNECTING);host.setVisibility(View.VISIBLE);line.layout(0,0,300,2);line.onDraw(c);assertEquals(AgentIndicatorState.State.RECONNECTING,b.state());assertTrue("return frame: attached="+line.isAttachedToWindow()+", shown="+line.isShown()+", window="+line.getWindowVisibility(),pending.getBoolean(line));org.robolectric.util.ReflectionHelpers.setField(attach,"mWindowVisibility",View.GONE);line.onWindowVisibilityChanged(View.GONE);assertFalse(pending.getBoolean(line));org.robolectric.util.ReflectionHelpers.setField(attach,"mWindowVisibility",View.VISIBLE);line.onWindowVisibilityChanged(View.VISIBLE);line.onDraw(c);assertTrue(pending.getBoolean(line));line.working(false);assertFalse(pending.getBoolean(line));}
  finally{line.working(false);host.removeAllViews();a.finish();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 }

 @Test public void agentNeverAttachesOuterRouteAndOrdinarySessionsKeepLine(){Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a);WorkspaceActivityLine line=new WorkspaceActivityLine(a,null);AgentStopButton b=new AgentStopButton(a);host.addView(line,new FrameLayout.LayoutParams(300,2));host.addView(b,new FrameLayout.LayoutParams(44,44));a.setContentView(host);line.layout(0,0,300,2);b.layout(200,10,244,54);Canvas c=new Canvas(Bitmap.createBitmap(300,60,Bitmap.Config.ARGB_8888));line.stopTarget(b);b.indicator("Codex",AgentIndicatorState.State.WORKING);line.working(true);line.onDraw(c);assertFalse(line.routing());line.stopTarget(null);line.onDraw(c);assertTrue(line.working());line.working(false);assertFalse(line.working());host.removeView(line);}
 @Test public void disabledSystemAnimationsDoNotScheduleAFrameLoop()throws Exception{java.lang.reflect.Method scale=android.animation.ValueAnimator.class.getDeclaredMethod("setDurationScale",float.class);scale.setAccessible(true);scale.invoke(null,0f);Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a);WorkspaceActivityLine line=new WorkspaceActivityLine(a,null);AgentStopButton b=new AgentStopButton(a);host.addView(line,new FrameLayout.LayoutParams(300,2));host.addView(b,new FrameLayout.LayoutParams(44,44));a.setContentView(host);line.layout(0,0,300,2);Object attach=org.robolectric.util.ReflectionHelpers.getField(line,"mAttachInfo");org.robolectric.util.ReflectionHelpers.setField(attach,"mWindowVisibility",View.VISIBLE);line.onWindowVisibilityChanged(View.VISIBLE);line.stopTarget(b);try{for(String agent:new String[]{"Codex","Claude","Gemini","OpenCode"}){b.indicator(agent,AgentIndicatorState.State.WORKING);line.working(true);line.onDraw(new Canvas(Bitmap.createBitmap(300,2,Bitmap.Config.ARGB_8888)));java.lang.reflect.Field frame=WorkspaceActivityLine.class.getDeclaredField("framePending");frame.setAccessible(true);assertEquals(View.VISIBLE,line.getWindowVisibility());assertFalse(frame.getBoolean(line));assertEquals(1,b.glyphScale(),0);assertEquals(1,b.elementBrightness(0,12),0);}}finally{line.working(false);scale.invoke(null,1f);}}
 @Test public void codexBrightnessHasSmoothDeeperPhasesWithoutChangingPeriod(){
  Activity a=Robolectric.buildActivity(Activity.class).get();AgentStopButton b=new AgentStopButton(a);b.indicator("Codex",AgentIndicatorState.State.WORKING);b.frame(1,0);assertEquals(.48f,b.codexBrightness(),.001f);b.frame(1400000000L,0);assertEquals(1,b.codexBrightness(),.001f);b.frame(2800000001L,0);assertEquals(.48f,b.codexBrightness(),.001f);b.frame(0,0);assertEquals(1,b.codexBrightness(),0);a.finish();
 }

}
